create table options (presentation_oder integer, id uuid not null, caption varchar(255), primary key (id));
create table polls (created_by_id bigint, id bigint generated by default as identity, published_at timestamp(6) with time zone, valid_until timestamp(6) with time zone, question varchar(255), primary key (id));
create table polls_vote_options (poll_id bigint not null, vote_options_id uuid not null unique);
create table users (id bigint generated by default as identity, email varchar(255) not null unique, username varchar(255) not null unique, primary key (id));
create table users_voted (user_id bigint not null, voted_id uuid not null unique, primary key (user_id, voted_id));
create table votes (published_at timestamp(6) with time zone, id uuid not null, voted_on_id uuid, primary key (id));
