alter table if exists polls_vote_options add constraint FKkfbc8bu7e456as34lyrl1hjky foreign key (vote_options_id) references options;
alter table if exists polls_vote_options add constraint FKmtcd0p2feecd6j6yuc966ud52 foreign key (poll_id) references polls;
alter table if exists users_voted add constraint FK889ph0bvdpavkgjtj2fs549ri foreign key (voted_id) references votes;
